EVT_KO_SCALE = 0.72        -- size (retail 1.0)
EVT_KO_SQUARE = false      -- (the plate picture is repainted at build; true = the old run-time cmd_base01 swap)
EVT_KO_HIDE_GLOW = true    -- hide _restart_btn_base_add01 / 02 (the additive glow / blink)
EVT_KO_ALPHA = 1.0         -- extra plate opacity (1 = none: the repainted plate is already 85 %); the text keeps full opacity
EVT_KO_CENTRE_Y = 150      -- plate centre height in the layout (_pos_btn01 y 150; joints are centred on it): kept when scaling

local EVT_KO_LAYER = 1684251946 --[[soccer00_27_restart_button]]
local EVT_KO_ATLAS_0808 = 1822283221 --[[#/menu/00_soccer/soccer08/soccer08_08/<LG>/soccer08_08.g4tx]]
local EVT_KO_CMD_BASE = 2905228853 --[[cmd_base01]]
local EVT_KO_SLOT = 1641261638 --[[restart_btn_base01: the pill's sprite slot]]
local EVT_KO_MESH = 3239439752 --[[_restart_btn_base01]]
local EVT_KO_ADD = {3354808620 --[[_restart_btn_base_add01]], 1593770134 --[[_restart_btn_base_add02]]}
local evt_ko_closing = false
local evt_ko_idx = nil

-- «(Y) Formación» above «(A) Reanudar»
EVT_PP_GAP = 8              -- screen units between the two plates
EVT_PP_FORM_SCALE = 1.0     -- wanted overall scale of «Formación» (its plate is 52 units tall; «Reanudar»'s is 72 x 0.72)
local EVT_PP_FORM = 81089765 --[[soccer01_33_formation_button_guide]]
local EVT_PP_N_POS = 3118168032 --[[_pos_btn01]]
local EVT_PP_N_TOUCH = 830613497 --[[_touch_btn01: the plate's top-left corner, (-220, +36) from _pos_btn01]]
local EVT_PP_TOUCH_DX = -220
local EVT_PP_N_FBASE = 1517329426 --[[_pos_base01 of soccer01_33: the plate's top-left corner]]
local EVT_PP_N_FTEXT = 378156699 --[[_text_guide01 of soccer01_33: 56 units right of it]]
local EVT_PP_FTEXT_DX = 56
local EVT_PP_FORM_H = 52
local EVT_PP_REST_W = 388            -- «Reanudar»'s plate width in layout units (content\menus\pause_prompts.toml)
local evt_pp_idx = nil
local evt_pp_s = 1
local evt_pp_lx, evt_pp_ly = 0, 0

local function EVT_KO_Cmd(...)
  if type(funcLuaMenuCommand) == "function" then
    return pcall(funcLuaMenuCommand, ...)
  end
  return false
end

local function EVT_KO_Look(idx)
  if EVT_KO_HIDE_GLOW then
    for i = 1, #EVT_KO_ADD do
      EVT_KO_Cmd(3405944500 --[[CMND_SET_MESH_VISIBLE]], EVT_KO_LAYER, EVT_KO_ADD[i], false, idx)
    end
  end
  if EVT_KO_ALPHA < 1 and not evt_ko_closing then
    -- the prim of the plate by sprite and by mesh name (whichever the engine keys it by)
    EVT_KO_Cmd(2219773080 --[[CMND_SET_PRIM_ALPHA]], EVT_KO_LAYER, idx, EVT_KO_SLOT, EVT_KO_ALPHA)
    EVT_KO_Cmd(2219773080 --[[CMND_SET_PRIM_ALPHA]], EVT_KO_LAYER, idx, EVT_KO_MESH, EVT_KO_ALPHA)
  end
end

local function EVT_PP_Gp(layer, idx, node)
  local ok, x, y = pcall(funcLuaMenuCommand, 499270986 --[[CMND_GET_MESH_GLOBAL_POSITION]], layer, idx, node)
  if ok and type(x) == "number" and type(y) == "number" then
    return x, y
  end
  return nil
end

-- every Step while «Formación» is open: scale 1, its plate's top-left corner = «Reanudar»'s plate top-left corner + one
-- row up. Measured, then corrected by the residual (an off estimate of the layer's local unit only slows the
-- convergence; scale first, then position)
local function EVT_PP_Place()
  if evt_pp_idx == nil or evt_ko_idx == nil or evt_ko_closing
      or rawget(_ENV, "EVT_UI_PRESET") == "off" then
    return
  end
  local okOpen, open = pcall(funcLuaMenuCommand, 2640875187 --[[CMND_IS_OPEN_LAYER]], EVT_PP_FORM, evt_pp_idx)
  if not okOpen or open ~= true then
    return
  end
  local px, py = EVT_PP_Gp(EVT_KO_LAYER, evt_ko_idx, EVT_PP_N_POS)
  local tx, ty = EVT_PP_Gp(EVT_KO_LAYER, evt_ko_idx, EVT_PP_N_TOUCH)
  local fx0, fy0 = EVT_PP_Gp(EVT_PP_FORM, evt_pp_idx, EVT_PP_N_FBASE)
  local fx1 = EVT_PP_Gp(EVT_PP_FORM, evt_pp_idx, EVT_PP_N_FTEXT)
  if px == nil or tx == nil or fx0 == nil or fx1 == nil then
    return
  end
  local kr = (tx - px) / EVT_PP_TOUCH_DX
  local kf = (fx1 - fx0) / EVT_PP_FTEXT_DX
  if kr < 0.05 or kr > 5 or kf < 0.05 or kf > 5 then
    return
  end
  if math.abs(kf - EVT_PP_FORM_SCALE) > 0.03 then
    evt_pp_s = evt_pp_s * EVT_PP_FORM_SCALE / kf
    EVT_KO_Cmd(3778714801 --[[CMND_SET_LAYER_LOCAL_SCALE]], EVT_PP_FORM, evt_pp_s, evt_pp_s, 1, evt_pp_idx)
    return
  end
  local dir = (ty >= py) and 1 or -1 -- screen y direction of "up" (the touch node is above _pos_btn01)
  -- centred on «Reanudar»'s plate: its left edge + half the difference of the two plate widths (the text plate grows
  -- with its text: width from CMND_GET_LAYER_WIDTH; «Reanudar»'s plate is EVT_PP_REST_W layout units x its scale)
  local targetX = tx
  local okW, fw = pcall(funcLuaMenuCommand, 1775716383 --[[CMND_GET_LAYER_WIDTH]], EVT_PP_FORM, evt_pp_idx, true, true)
  if okW and type(fw) == "number" and fw > 0 then
    targetX = tx + (EVT_PP_REST_W * kr - fw * kf) / 2
  end
  local ex = targetX - fx0
  local ey = ty + dir * (EVT_PP_GAP + EVT_PP_FORM_H * kf) - fy0
  if math.abs(ex) < 0.75 and math.abs(ey) < 0.75 then
    return
  end
  evt_pp_lx = evt_pp_lx + ex / kf
  evt_pp_ly = evt_pp_ly + ey * dir / kf
  EVT_KO_Cmd(1389957207 --[[CMND_SET_LAYER_LOCAL_POS]], EVT_PP_FORM, evt_pp_lx, evt_pp_ly, 0, evt_pp_idx)
end

local function EVT_KO_Setup(idx)
  if rawget(_ENV, "EVT_UI_PRESET") == "off" then
    return
  end
  evt_ko_idx = idx
  evt_ko_closing = false
  local s = EVT_KO_SCALE
  EVT_KO_Cmd(3778714801 --[[CMND_SET_LAYER_LOCAL_SCALE]], EVT_KO_LAYER, s, s, 1, idx)
  -- scaled around the layer origin (bottom centre): move it back up so the pill keeps its centre height
  EVT_KO_Cmd(1389957207 --[[CMND_SET_LAYER_LOCAL_POS]], EVT_KO_LAYER, 0, math.floor(EVT_KO_CENTRE_Y * (1 - s) + 0.5), 0, idx)
  if EVT_KO_SQUARE then
    EVT_KO_Cmd(558735651 --[[swap texture]], EVT_KO_LAYER, EVT_KO_ATLAS_0808, EVT_KO_CMD_BASE, EVT_KO_SLOT, 0, idx)
  end
  EVT_KO_Look(idx)
  pcall(funcLuaCommand, 3661580131 --[[CMND_EVT_LOG]], "ui_clean kickoff button", "scale " .. tostring(s),
    "square " .. tostring(EVT_KO_SQUARE), "alpha " .. tostring(EVT_KO_ALPHA))
end

local evt_ko_prevSetup = rawget(_ENV, "OnSetupLayer")
if type(evt_ko_prevSetup) == "function" then
